 function showGrounded(result,jobId){content.replaceChildren(notice(`Recherche Internet Gemini · ${result.candidates.length} candidat(s), ${result.sources.length} source(s) citée(s), ${result.search_query_count} recherche(s) exécutée(s). Aucun candidat n’est vérifié ou importé par défaut.`,true));for(const item of result.candidates)content.append(candidateCard(item,false,jobId));if(result.sources.length)content.append(panel('Sources citées par Google Search',h('div',{},result.sources.map(s=>h('p',{},link(s.title+' ↗',s.url))))));if(result.search_suggestions.length)content.append(panel('Suggestions de recherche Google',h('div',{},result.search_suggestions.map(s=>h('p',{},link(s.text+' ↗',s.url))))));}
